theorem imo2019_p1 (f : ℤ → ℤ) :
    (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) ↔ f ∈ solution_set  := by
  constructor; swap;
  intro hf a b;
  cases' hf with hf1 hf2;
  simp [hf1];
  obtain ⟨c, hc⟩ := hf2;
  simp [hc];
  ring;
  intro hf;
  let g : ℤ → ℤ := fun z => f(z) - f(0);
  have hg : ∀z, g(z) = f(z) - f(0) := fun z => by rfl;
  have h : ∀ x y, g (x + y) = g (x) + g (y) := by
    intro x y;
    simpa using hf 0 (x + y), hf x y, hf x 0, hf 0 x;
  have h' : ∃ d, ∀ z, g(z) = d * z := additive_to_int_linear g h;
  cases h' with;
  case inl => exact ⟨f(0), hg, sub_add_cancel⟩;
  case inr => exact ⟨f(0), hg, fun z => by rw [← sub_eq_add_neg, ← sub簧_eq_ne, Int.mul_left_eq_self_right, zero_mul]⟩끊;
